import zlib from 'zlib';

const embeddedAfmCompressed: Record<string, string> = {
  "Courier-Bold.afm": "",
  "Courier-BoldOblique.afm": "",
  "Courier-Oblique.afm": "",
  "Courier.afm": "",
  "Helvetica-Bold.afm": "",
  "Helvetica-BoldOblique.afm": "",
  "Helvetica-Oblique.afm": "",
  "Helvetica.afm": "",
  "Symbol.afm": "",
  "Times-Bold.afm": "",
  "Times-BoldItalic.afm": "",
  "Times-Italic.afm": "",
  "Times-Roman.afm": "",
  "ZapfDingbats.afm": ""
};

const fontCache = new Map<string, string>();

export function getEmbeddedAfm(filename: string): string | null {
  const cleanName = filename.split(/[/\\]/).pop() || filename;
  if (fontCache.has(cleanName)) return fontCache.get(cleanName)!;
  const b64 = embeddedAfmCompressed[cleanName];
  if (!b64) return null;
  try {
    const inflated = zlib.inflateSync(Buffer.from(b64, 'base64')).toString('utf8');
    fontCache.set(cleanName, inflated);
    return inflated;
  } catch {
    return null;
  }
}
